'use strict';
const {initial,actions,step}=Game;
const icons={knight:'♘',jumper:'◇',pusher:'↑',king:'♚',hunter:'♟',guard:'♜'};
const names={knight:'기사',jumper:'도약자',pusher:'밀치기병',king:'왕',hunter:'추적자',guard:'수호자'};
const descriptions={knight:'상하좌우 한 칸 이동합니다. 도착한 칸의 적을 잡습니다.',jumper:'상하좌우 정확히 두 칸 이동합니다. 중간의 말·벽을 뛰어넘고 도착한 칸의 적을 잡습니다.',pusher:'상하좌우 한 칸 이동합니다. 말이 있으면 뒤의 빈칸으로 한 칸 밀어냅니다. 직접 잡을 수는 없습니다.',king:'움직이지 않습니다. 이 말을 목표 턴 안에 잡으면 승리합니다. 밀치기로 위치가 바뀔 수 있습니다.',hunter:'상하좌우 한 칸 이동하고 백을 잡습니다. AI가 공격·수비·후퇴 중 유리한 수를 선택합니다.',guard:'상하좌우·대각선으로 한 칸 이동하고 백을 잡습니다. AI가 왕 방어와 반격을 판단합니다.'};
let index=0,state=initial(LEVELS[0]),selected=null,inspected=null,history=[],completed={},busy=false,inspectMode=false,epoch=0;
try{let saved=JSON.parse(localStorage.getItem('three-moves-hard-v2')||'{}');if(saved&&typeof saved==='object'&&!Array.isArray(saved))completed=saved;}catch{}
const $=id=>document.getElementById(id),coord=pos=>'ABCDEF'[pos%6]+(Math.floor(pos/6)+1);
function load(i){epoch++;busy=false;index=i;state=initial(LEVELS[i]);selected=null;inspected=null;history=[];inspectMode=false;render();}
function render(){const level=LEVELS[index],possible=!busy&&state.status==='play'&&!inspectMode?actions(state,'w').filter(m=>m.id===selected):[];
$('progress').textContent=Object.keys(completed).filter(k=>Number(k)>=0&&Number(k)<10).length+' / 10';$('levels').innerHTML=LEVELS.map((l,i)=>`<button class="level ${i===index?'active':''}" data-level="${i}" aria-label="스테이지 ${i+1} ${l.name}${completed[i]?' 완료':''}" aria-current="${i===index?'step':'false'}"><span class="num">${String(i+1).padStart(2,'0')}</span><span class="name">${l.name}</span><span class="check">${completed[i]?'✓':''}</span></button>`).join('');document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>load(+b.dataset.level));$('chapter').textContent='STAGE '+String(index+1).padStart(2,'0')+' / HARD';$('title').textContent=level.name;$('target').textContent=level.limit;$('turn').textContent=state.turn;$('board').innerHTML='';
for(let pos=0;pos<36;pos++){let p=state.pieces.find(p=>p.pos===pos),wall=state.walls.includes(pos),m=possible.find(m=>m.to===pos),b=document.createElement('button');b.className='cell '+((pos%6+Math.floor(pos/6))%2?'dark ':'')+(wall?'wall ':'')+(m?'possible ':'')+(p&&p.id===selected?'selected':'');b.setAttribute('aria-label',coord(pos)+(wall?' 벽':p?' '+(p.side==='w'?'백 ':'흑 ')+names[p.type]:' 빈칸')+(m?' 이동 가능':''));b.setAttribute('aria-pressed',p&&p.id===selected?'true':'false');b.innerHTML=(pos%6===0?`<span class="rank">${Math.floor(pos/6)+1}</span>`:'')+(p?`<span class="piece ${p.side} ${p.type==='king'?'king':''}">${icons[p.type]}</span>`:'');b.onclick=()=>{if(busy)return;if(inspectMode){inspected=p?.id||null;render();return;}if(m&&state.status==='play'){move(m);return;}if(p){inspected=p.id;selected=p.side==='w'&&state.status==='play'?(selected===p.id?null:p.id):null;}else{selected=null;inspected=null;}render();};b.oncontextmenu=e=>{e.preventDefault();inspected=p?.id||null;render();};$('board').appendChild(b);}
let p=state.pieces.find(p=>p.id===inspected);$('piece-info').innerHTML=(p?`<span class="info-token ${p.side}">${icons[p.type]}</span><div><strong>${p.side==='w'?'백':'흑'} · ${names[p.type]} <span style="font-weight:400;color:#8a9480">${coord(p.pos)}</span></strong><p>${descriptions[p.type]}</p></div>`:'<span class="info-placeholder">말을 클릭하거나 우클릭하면 설명이 나옵니다.</span>')+`<button id="inspect" class="inspect" aria-pressed="${inspectMode}">${inspectMode?'설명 닫기':'말 설명'}</button>`;$('inspect').onclick=()=>{inspectMode=!inspectMode;selected=null;render();};$('undo').disabled=!history.length||busy;$('reset').disabled=false;$('status').textContent=busy?'흑이 생각 중…':state.status==='win'?'성공':state.status==='lose'?'도전 종료':inspectMode?'설명 모드':`백의 차례 · ${Math.max(0,level.limit-state.turn)}턴 남음`;
$('result').innerHTML=state.status==='win'?`<strong>${state.turn}턴. 왕을 잡았습니다.</strong><p>${index===9?'모든 도전의 마지막에 도착했습니다.':'다음 판에서도 한 수 앞을 읽어보세요.'}</p><button id="next">${index===9?'첫 스테이지로':'다음 스테이지 →'}</button>`:state.status==='lose'?`<strong>${state.reason==='limit'?'목표 턴을 모두 사용했습니다.':'왕을 잡을 전력이 사라졌습니다.'}</strong><p>되돌리거나 다시 시작해 다른 수를 찾아보세요.</p>`:'';if($('next'))$('next').onclick=()=>load((index+1)%10);}
function move(m){const token=epoch;history.push(Game.copy(state));busy=true;selected=null;inspected=null;render();setTimeout(()=>{if(token!==epoch)return;state=step(state,m);busy=false;if(state.status==='win'){completed[index]=state.turn;try{localStorage.setItem('three-moves-hard-v2',JSON.stringify(completed))}catch{}}render();},35);}
$('undo').onclick=()=>{if(history.length&&!busy){epoch++;state=history.pop();selected=null;inspected=null;render();}};$('reset').onclick=()=>load(index);$('help').onclick=()=>$('rules').showModal();$('close').onclick=()=>$('rules').close();document.addEventListener('keydown',e=>{if($('rules').open||e.ctrlKey||e.metaKey||e.altKey)return;if(e.key.toLowerCase()==='z')$('undo').click();if(e.key.toLowerCase()==='r')$('reset').click();if(e.key==='Escape'){selected=null;inspected=null;inspectMode=false;render();}});render();
